        const prev = previous;
        previous = next;
        fn(next, prev);
      }
    };
    previous = read();
    reactionWatchers.push(watcher);
  },
  useAnimatedScrollHandler: (fn) => fn,
  scrollTo: (_ref, _x, y) => scrolls.push(y),
  withTiming: (value, config, cb) => {
    timings.push(config?.duration);
