  },
  withDecay: (config, cb) => {
    if (cb) queueMicrotask(() => cb(true));
    return config;
  },
  Easing: { out: () => ({}), cubic: {} },
  interpolate: (v, input, output) => {
    const t = input[0] === input[1] ? 1 : (v - input[0]) / (input[1] - input[0]);
