import { getApiBaseUrl } from '@/lib/apiConfig';

export type ApiSuccess<T> = {
  success: true;
  data: T;
  message?: string;
};

export type ApiFailure = {
  success: false;
  error: string;
  details?: { field: string; message: string }[];
};

export class ApiError extends Error {
  status: number;
  details?: { field: string; message: string }[];

  constructor(message: string, status: number, details?: { field: string; message: string }[]) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.details = details;
  }
}

type RequestOptions = {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  body?: unknown;
  token?: string | null;
  signal?: AbortSignal;
};

let authTokenProvider: (() => string | null | undefined) | null = null;

export function setApiAuthTokenProvider(provider: () => string | null | undefined) {
  authTokenProvider = provider;
}

export async function apiRequest<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const baseUrl = getApiBaseUrl();
  const token = options.token === undefined ? (authTokenProvider?.() ?? null) : options.token;
  const headers: Record<string, string> = {
    Accept: 'application/json',
  };

  if (options.body !== undefined) {
    headers['Content-Type'] = 'application/json';
  }
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  const controller = new AbortController();
  const abort = () => controller.abort();
  options.signal?.addEventListener('abort', abort, { once: true });
  if (options.signal?.aborted) controller.abort();
  // Allow a Render cold start without indefinite waits or automatic write retries.
  const timeout = setTimeout(abort, 90_000);
  let response: Response;
  let payload: ApiSuccess<T> | ApiFailure | null;
  try {
    response = await fetch(`${baseUrl}${path}`, {
      method: options.method ?? 'GET',
      headers,
      body: options.body === undefined ? undefined : JSON.stringify(options.body),
      signal: controller.signal,
    });
    payload = await response.json().catch(() => null);
  } catch {
    throw new ApiError('Unable to reach the backend. Check your network and API URL.', 0);
  } finally {
    clearTimeout(timeout);
    options.signal?.removeEventListener('abort', abort);
  }

  if (!response.ok || !payload || payload.success === false) {
    const failure = payload && 'error' in payload ? payload : null;
    throw new ApiError(
      failure?.error ?? `Request failed (${response.status})`,
      response.status,
      failure?.details,
    );
  }

  return payload.data;
}

export async function checkBackendHealth(): Promise<boolean> {
  try {
    await apiRequest<{ status: string }>('/health');
    return true;
  } catch {
    return false;
  }
}

let lastWakeVerifiedAt = 0;
let pendingWake: Promise<boolean> | null = null;
const WAKE_REUSE_WINDOW_MS = 15_000;

/**
 * Best-effort `/health` ping so a sleeping Render instance starts warming up.
 * Returns true when the backend answers (or was verified very recently).
 */
export async function wakeBackend(): Promise<boolean> {
  if (Date.now() - lastWakeVerifiedAt < WAKE_REUSE_WINDOW_MS) return true;
  if (!pendingWake) pendingWake = checkBackendHealth().then((awake) => {
    if (awake) lastWakeVerifiedAt = Date.now();
    return awake;
  }).finally(() => { pendingWake = null; });
  return pendingWake;
}

/**
 * Backend-backed providers all share one Render instance that sleeps when idle.
 * A first request can therefore fail purely because the instance is cold.
 *
 * On a cold-start-shaped failure (network error / 502-504) we ping `/health` to
 * trigger the wake-up and retry exactly once. A sleeping backend is never
 * mistaken for a broken source, and a provider is never permanently disabled
 * because the first Render request timed out.
 */
export async function apiRequestWithWake<T>(
  path: string,
  options: RequestOptions = {},
): Promise<T> {
  try {
    return await apiRequest<T>(path, options);
  } catch (error) {
    if (options.signal?.aborted || (options.method && options.method !== 'GET')) throw error;
    const status = error instanceof ApiError ? error.status : -1;
    const looksLikeColdStart = status === 0 || status === 502 || status === 503 || status === 504;
    if (!looksLikeColdStart) throw error;
    const awake = await wakeBackend();
    if (!awake) throw error;
    return apiRequest<T>(path, options);
  }
}

import * as FileSystem from 'expo-file-system/legacy';
import { Platform } from 'react-native';

const isWeb = Platform.OS === 'web';
const memoryStorage = new Map<string, string>();

/**
 * Returns the base downloads directory path.
 */
export function getBaseDownloadsDir(): string {
  if (isWeb || !FileSystem.documentDirectory) {
    return 'memory://downloads/';
  }
  return `${FileSystem.documentDirectory}downloads/`;
}

export function getAnimeStoragePath(animeId: string, episodeId: string): string {
  return `${getBaseDownloadsDir()}anime/${animeId}/${episodeId}/video.mp4`;
}

export function getMangaChapterStorageDir(mangaId: string, chapterId: string): string {
  return `${getBaseDownloadsDir()}manga/${mangaId}/${chapterId}/`;
}

export function getNovelChapterStoragePath(novelId: string, chapterId: string): string {
  return `${getBaseDownloadsDir()}novel/${novelId}/${chapterId}/chapter.json`;
}

export async function ensureDirectory(dirUri: string): Promise<void> {
  if (isWeb || !FileSystem.documentDirectory) {
    return;
  }
  try {
    const dirInfo = await FileSystem.getInfoAsync(dirUri);
    if (!dirInfo.exists) {
      await FileSystem.makeDirectoryAsync(dirUri, { intermediates: true });
    }
  } catch (error) {
    // console.warn(`[storageService] Failed to ensure directory ${dirUri}:`, error);
  }
}

export async function checkFileExists(fileUri: string | null): Promise<boolean> {
  if (!fileUri) return false;
  if (isWeb || !FileSystem.documentDirectory) {
    return memoryStorage.has(fileUri);
  }
  try {
    const info = await FileSystem.getInfoAsync(fileUri);
    return info.exists;
  } catch {
    return false;
  }
}

export async function saveTextFile(fileUri: string, content: string): Promise<void> {
  if (isWeb || !FileSystem.documentDirectory)
    throw new Error('Offline video downloads require Android or iOS.');
  await ensureDirectory(fileUri.slice(0, fileUri.lastIndexOf('/') + 1));
  await FileSystem.writeAsStringAsync(fileUri, content);
}

export async function saveJsonFile(fileUri: string, data: unknown): Promise<void> {
  const content = JSON.stringify(data);
  if (isWeb || !FileSystem.documentDirectory) {
    memoryStorage.set(fileUri, content);
    return;
  }
  const dir = fileUri.substring(0, fileUri.lastIndexOf('/') + 1);
  await ensureDirectory(dir);
  await FileSystem.writeAsStringAsync(fileUri, content, {
    encoding: FileSystem.EncodingType.UTF8,
  });
}

export async function readJsonFile<T>(fileUri: string): Promise<T | null> {
  if (isWeb || !FileSystem.documentDirectory) {
    const cached = memoryStorage.get(fileUri);
    return cached ? (JSON.parse(cached) as T) : null;
  }
  try {
    const exists = await checkFileExists(fileUri);
    if (!exists) return null;
    const content = await FileSystem.readAsStringAsync(fileUri, {
      encoding: FileSystem.EncodingType.UTF8,
    });
    return JSON.parse(content) as T;
  } catch (error) {
    // console.warn(`[storageService] Failed to read JSON from ${fileUri}:`, error);
    return null;
  }
}

export async function deleteStoragePath(targetUri: string): Promise<void> {
  if (isWeb || !FileSystem.documentDirectory) {
    memoryStorage.delete(targetUri);
    for (const key of Array.from(memoryStorage.keys())) {
      if (key.startsWith(targetUri)) {
        memoryStorage.delete(key);
      }
    }
    return;
  }
  try {
    const info = await FileSystem.getInfoAsync(targetUri);
    if (info.exists) {
      await FileSystem.deleteAsync(targetUri, { idempotent: true });
    }
  } catch (error) {
    // console.warn(`[storageService] Failed to delete storage path ${targetUri}:`, error);
  }
}

export type DownloadProgressCallback = (progress: {
  totalBytesWritten: number;
  totalBytesExpectedToWrite: number;
  progress: number;
}) => void;

/**
 * Downloads a single file with progress tracking and resumable support.
 */
export async function downloadFile(
  remoteUrl: string,
  destinationUri: string,
  onProgress?: DownloadProgressCallback,
): Promise<{ uri: string; size: number }> {
  if (isWeb || !FileSystem.documentDirectory) {
    throw new Error('Offline media downloads require the Android or iOS app.');
  }

  const dir = destinationUri.substring(0, destinationUri.lastIndexOf('/') + 1);
  await ensureDirectory(dir);

  const downloadResumable = FileSystem.createDownloadResumable(
    remoteUrl,
    destinationUri,
    {},
    (downloadProgress) => {
      const { totalBytesWritten, totalBytesExpectedToWrite } = downloadProgress;
      const progress =
        totalBytesExpectedToWrite > 0
          ? Math.min(Math.max(totalBytesWritten / totalBytesExpectedToWrite, 0), 1)
          : 0;
      onProgress?.({
        totalBytesWritten,
        totalBytesExpectedToWrite,
        progress,
      });
    },
  );

  const result = await downloadResumable.downloadAsync();
  if (!result || !result.uri || result.status < 200 || result.status >= 300) {
    throw new Error('Download failed to return a valid local file URI');
  }

  const fileInfo = await FileSystem.getInfoAsync(result.uri);
  const size = (fileInfo as { size?: number }).size ?? 0;

  return {
    uri: result.uri,
    size,
  };
}
